package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

/** A comment needs some text (an empty or blank one is refused); a viewer, or any user on an archived sheet, is refused. */
public class ValidateComment {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody CommentRequest request, Out<CommentRequest> body,
            Settings settings) throws ViewerRefusedException, InvalidClaimException {
        settings.refuseViewer(sheetId, request.user());
        if (request.text() == null || request.text().isBlank()) {
            throw new InvalidClaimException("A comment needs some text");
        }
        body.set(request);
    }
}
package net.officefloor.hq.app.claim;

/** Body of POST /api/sheets/{sheetId}/claims/{claimId}/comment: who comments the claim, and the comment. */
public record CommentRequest(String text, String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            Claims claims, Out<Claim> claimOut) throws ClaimNotFoundException {
        Claim claim = null;
        try {
            claim = claims.find(sheetId, Long.parseLong(claimId));
        } catch (NumberFormatException e) {
            // not an id this app assigned
        }
        if (claim == null) {
            throw new ClaimNotFoundException(claimId);
        }
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

/** Keeps the comment on the claim, with its user and the sheet's today. */
public class SaveComment {
    public void save(@Val CommentRequest request, @Val Claim claim, Claims claims) {
        claims.comment(claim, request.user(), request.text().trim());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

public class AuditClaimCommented {
    public void audit(@Val CommentRequest request, @Val Claim claim, People people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.recordOnCommit(ClaimAudit.line("COMMENT_ADDED", request.user(), person, claim, claim.getNumber())
                + " text=" + request.text().trim());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaim {
    public void respond(@Val Claim claim, ObjectResponse<ClaimResponse> response) {
        response.send(ClaimResponse.from(claim));
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** A comment on a claim: the user who wrote it, the sheet's today when it was written, and its text. */
public record ClaimComment(String user, LocalDate date, String text) {

    /** The comment as a claim shows it: "<user> on <date>: <text>". */
    public String line() {
        return user + " on " + date + ": " + text;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidateClaim {

    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");
    private static final Pattern SIGNED_AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
    private static final Pattern NUMBER = Pattern.compile("\\d+|\\S+-\\d+");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ClaimRequest request, Out<ValidClaim> body, Settings settings)
            throws InvalidClaimException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        body.set(check(request));
    }

    /** The claim form's rules on its body alone; the sheet's rules are checked when the claim is saved. */
    static ValidClaim check(ClaimRequest request) throws InvalidClaimException {
        BigDecimal amount = signedAmount(request.amount());
        String corrects = corrects(request.corrects());
        if (amount.signum() < 0 && corrects == null) {
            throw new InvalidClaimException("A negative amount is a correction: it must name the claim it corrects");
        }
        if (amount.signum() >= 0 && corrects != null) {
            throw new InvalidClaimException("Only a correction (a negative amount) can name a claim it corrects");
        }
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("The date is not a date");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        String ref = request.ref() == null ? "" : request.ref().trim();
        return new ValidClaim(amount, date, note, request.user(), corrects, ref.isEmpty() ? null : ref, tags(request.tags()));
    }

    /** A claim's tags from the form's comma separated text (see {@link Tags#normalise}). */
    static String tags(String raw) {
        return Tags.normalise(raw);
    }

    /** The claim form's amount: with at most two decimals; a negative one is a correction. */
    static BigDecimal signedAmount(String raw) throws InvalidClaimException {
        String amount = raw == null ? "" : raw.trim();
        if (!SIGNED_AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must have at most two decimals");
        }
        return new BigDecimal(amount).setScale(2);
    }

    /** The number of the claim a correction corrects; null when blank. */
    static String corrects(String raw) throws InvalidClaimException {
        String corrects = raw == null ? "" : raw.trim();
        if (corrects.isEmpty()) return null;
        if (!NUMBER.matcher(corrects).matches()) {
            throw new InvalidClaimException("The claim corrected must be named by its number");
        }
        return corrects;
    }

    /** Refuse a correction that does not name a SETTLED claim of the same person. */
    static void checkCorrects(ValidClaim request, String sheetId, long personId, Claims claims) throws InvalidClaimException {
        if (request.corrects() != null && !claims.isSettled(sheetId, personId, request.corrects())) {
            throw new InvalidClaimException("A correction must name a SETTLED claim of the same person");
        }
    }

    /** Refuse a reference another claim on the sheet already carries (compared without regard to case). */
    static void checkRef(String ref, String sheetId, Long exceptId, Claims claims) throws InvalidClaimException {
        if (ref != null && claims.refUsed(sheetId, ref, exceptId)) {
            throw new InvalidClaimException("The reference " + ref + " is already used on the sheet");
        }
    }

    /** A claim's amount: 0.00 or more, with at most two decimals. */
    static BigDecimal amount(String raw) throws InvalidClaimException {
        String amount = raw == null ? "" : raw.trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be 0.00 or more, with at most two decimals");
        }
        return new BigDecimal(amount).setScale(2);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

public class ApplyClaim {
    public void apply(@Val ValidClaim request, @Val Claim claim, Sheets sheets, Periods periods, People people, Claims claims)
            throws InvalidClaimException {
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            // Only a draft can be edited; to change an open claim, void it and add a new one.
            throw new InvalidClaimException("Only a DRAFT claim can be edited");
        }
        String lockedBy = claims.lockedBy(claim);
        if (lockedBy != null && !lockedBy.equals(request.user())) {
            throw new InvalidClaimException("The claim is being edited by " + lockedBy);
        }
        LocalDate date = request.date() != null ? request.date() : sheets.today(claim.getSheetId());
        if (periods.isClosed(claim.getSheetId(), claim.getPeriodDate())) {
            throw new InvalidClaimException("No claim whose due-by is inside a closed period can be edited");
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        if (person != null && !person.allowsClaimOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
        }
        ValidateClaim.checkCorrects(request, claim.getSheetId(), claim.getPersonId(), claims);
        ValidateClaim.checkRef(request.ref(), claim.getSheetId(), claim.getId(), claims);
        claim.setAmount(request.amount());
        claim.setRef(request.ref());
        claim.setTags(request.tags());
        claim.setCorrects(request.corrects());
        claim.setCorrectedDate(claims.correctedDate(claim.getSheetId(), claim.getPersonId(), request.corrects()));
        claim.setDate(date);
        claim.setNote(request.note());
        claim.setEditedBy(request.user());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class SaveClaim {
    public void save(@Val Claim claim, Claims claims) {
        claims.save(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.person.People;
import net.officefloor.plugin.variable.Val;

public class AuditClaimEdited {
    public void audit(@Val ValidClaim request, @Val Claim claim, People people, Audit audit, @Val RollupFigures before, Rollup rollup) {
        audit.recordOnCommit(ClaimAudit.line("CLAIM_EDITED", request.user(),
                people.find(claim.getSheetId(), claim.getPersonId()), claim, claim.getNumber()));
        rollup.recordChanges(claim.getSheetId(), request.user(), before);
    }
}

